?><style>*{box-sizing:border-box}.container{max-width:1200px;margin:30px auto;padding:0 16px}.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px;align-items:start}.tool-main,.tool-sidebar{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:25px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.input{width:100%;padding:12px;border:1px solid #dfe4ec;border-radius:10px;font:inherit;margin:8px 0 14px}.btn{border:0;border-radius:10px;padding:12px 18px;background:#635bff;color:#fff;font-weight:800;cursor:pointer;margin:4px 5px 10px 0}.swatch{width:100%;height:100px;border-radius:14px;border:1px solid #ddd;margin:15px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{padding:14px;border:1px solid #e5e9f0;border-radius:12px;background:#f7f8fb}.card b{display:block;margin-bottom:5px}@media(max-width:800px){.tool-layout{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}.grid{grid-template-columns:1fr}}</style><main class="container"><div class="tool-layout"><section class="tool-main"><h1>Color Converter</h1><p>Convert colors between HEX, RGB, HSL and HSV instantly.</p><input id="input" class="input" value="#635BFF" placeholder="#635BFF, rgb(99,91,255) or hsl(243,100%,68%)"><button class="btn" onclick="convert()">Convert Color</button><input id="picker" type="color" value="#635bff" title="Choose a color"><div class="swatch" id="swatch"></div><div class="grid"><div class="card"><b>HEX</b><span id="hex">—</span></div><div class="card"><b>RGB</b><span id="rgb">—</span></div><div class="card"><b>HSL</b><span id="hsl">—</span></div><div class="card"><b>HSV</b><span id="hsv">—</span></div></div><br><button class="btn" onclick="copyAll()">Copy Values</button></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','sort-lines.php'=>'↕️ Sort Lines','remove-extra-spaces.php'=>'🧹 Remove Extra Spaces','reverse-text.php'=>'↔️ Reverse Text','text-to-slug.php'=>'🔗 Text to Slug','markdown-to-html.php'=>'📝 Markdown to HTML','html-encoder.php'=>'🔒 HTML Encoder','html-decoder.php'=>'🔓 HTML Decoder','url-encoder.php'=>'🔐 URL Encoder','url-decoder.php'=>'🔓 URL Decoder','base64-encoder.php'=>'🔒 Base64 Encoder','base64-decoder.php'=>'🔓 Base64 Decoder','color-converter.php'=>'🎨 Color Converter','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/smart-toolz/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/smart-toolz/tool.php">View All Tools →</a></aside></div></main><script>const input=document.getElementById('input'),picker=document.getElementById('picker');picker.oninput=()=>{input.value=picker.value;convert()};function parseColor(s){s=s.trim().toLowerCase();let m=s.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/);if(m){let h=m[1];if(h.length===3)h=h.split('').map(x=>x+x).join('');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]}m=s.match(/^rgba?\(\s*([\d.]+)[, ]+\s*([\d.]+)[, ]+\s*([\d.]+)/);if(m)return [+m[1],+m[2],+m[3]];throw Error('Invalid color')}function convert(){try{const [r,g,b]=parseColor(input.value),mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;let h=0,s=0,l=(mx+mn)/510,v=mx/255;if(d){h=60*(((mx===r?(g-b)/255:(mx===g?2+(b-r)/255:4+(r-g)/255)))%6);if(h<0)h+=360;s=d/(255-Math.abs(mx+mn-255))}const hex='#'+[r,g,b].map(x=>Math.round(x).toString(16).padStart(2,'0')).join('').toUpperCase();const hs=(h+360)%360;const hsvS=mx?d/mx:0;document.getElementById('hex').textContent=hex;document.getElementById('rgb').textContent=`rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;document.getElementById('hsl').textContent=`hsl(${Math.round(hs)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%)`;document.getElementById('hsv').textContent=`hsv(${Math.round(hs)}, ${Math.round(hsvS*100)}%, ${Math.round(v*100)}%)`;document.getElementById('swatch').style.background=hex;picker.value=hex}catch(e){document.getElementById('hex').textContent='Invalid color'}}function copyAll(){navigator.clipboard.writeText(`HEX: ${hex.textContent}\nRGB: ${rgb.textContent}\nHSL: ${hsl.textContent}\nHSV: ${hsv.textContent}`)}convert()</script><?php require_once __DIR__ . '/../footer.php'; ?>